// Romanian overlay for data/desserts.json (dessert recipe library).
// Keyed by recipe id — merged over the English base object at render time.
// Only name/steps/benefits/tip are translated. id, emoji, category, prep_time, servings,
// ingredients (item + amount_display), kcal, macros and fiber_g stay English-only/untouched —
// ingredients in particular are intentionally left untranslated to keep shopping-list/search
// matching logic simple and safe. Desserts have no vitamins_minerals field (that's juices-only).
const dessertsRo = {
  ds001: { name:"Trufe cu curmale și ciocolată neagră", steps:["Mixează migdalele în robotul de bucătărie până se mărunțesc fin.","Adaugă curmalele, pudra de cacao și vanilia. Mixează până se formează un aluat lipicios.","Formează 12 bile. Dă la congelator 10 minute.","Scufundă în ciocolată topită, presară fulgi de sare. Ține la frigider până se întăresc."], benefits:["Zaharurile naturale din curmale oferă energie de durată","Ciocolata neagră 85% aduce flavanoli antioxidanți","Fără zahăr rafinat sau ingrediente artificiale"], tip:"Rulează bilele neacoperite prin pudră de cacao sau fistic pisat pentru o variație rapidă." },
  ds002: { name:"Bomboane de cheesecake cu caju și vanilie", steps:["Bază: mixează curmalele și nuca de cocos până devin lipicioase. Presează într-o tavă de mini-brioșe tapetată cu hârtie.","Umplutură: mixează caju scurs, crema de cocos, lămâia, mierea și vanilia până obții o cremă fină și mătăsoasă.","Toarnă umplutura peste bază cu lingura. Dă la congelator 3 ore, până se întărește.","Scoate din formă și servește rece."], benefits:["Caju oferă grăsimi mononesaturate benefice pentru inimă","Zeama de lămâie accentuează gustul fără zahăr în plus","Fără lactate și fără zahăr rafinat"], tip:"Adaugă un fruct de pădure sau un fir de miere crudă chiar înainte de servire." },
  ds003: { name:"Crocant de ciocolată cu cacao și nucă de cocos", steps:["Tapetează o tavă de copt cu hârtie de copt.","Întinde ciocolata topită uniform, într-un strat de aproximativ 3mm.","Presară nucă de cocos, miez de cacao, migdale și sare de mare deasupra.","Dă la frigider 30 de minute, până se întărește complet. Sparge în bucăți neregulate."], benefits:["Miezul de cacao este una dintre cele mai bogate surse de magneziu","Antioxidanții din ciocolata neagră susțin sănătatea cardiovasculară","Fără zahăr adăugat, în afara celui natural din ciocolată"], tip:"Adaugă zmeură uscată sau coajă de portocală în ciocolata topită pentru o variantă rafinată." },
  ds004: { name:"Crocant de migdale cu miere crudă", steps:["Amestecă mierea și uleiul de cocos într-un bol. Adaugă migdalele și acoperă-le bine.","Întinde pe o tavă de copt tapetată, presară scorțișoară și sare.","Dă la frigider sau congelator 20 de minute, până se întărește.","Sparge în bucăți și păstrează într-un recipient etanș."], benefits:["Migdalele sunt bogate în vitamina E și grăsimi benefice pentru inimă","Mierea crudă păstrează enzime și antioxidanți naturali","Conținut ridicat de magneziu, util pentru relaxarea musculară"], tip:"Folosește migdale activate (înmuiate și deshidratate) pentru o digestie mai ușoară." },
  ds005: { name:"Trufe de nuci cu cacao", steps:["Mărunțește nucile în robotul de bucătărie până se macină fin.","Adaugă curmalele, cacaua, untul de migdale și vanilia. Procesează până se formează un aluat lipicios.","Formează 14 bile cu mâinile umede. Acoperă-le în pudră de cacao.","Ține la frigider 30 de minute înainte de servire."], benefits:["Nucile sunt cea mai bogată sursă de acizi grași omega-3 dintre toate nucile","Pudra de cacao are un conținut ridicat de fier și magneziu","Curmalele oferă crom, util pentru reglarea glicemiei"], tip:"Păstrează la frigider până la 2 săptămâni sau la congelator până la 3 luni." },
  ds006: { name:"Bomboane raw de tip carrot cake", steps:["Mărunțește nucile și curmalele până se combină grosier.","Adaugă morcovul ras, nuca de cocos și condimentele. Amestecă până compoziția se leagă.","Formează 16 bile. Ține la frigider 20 de minute.","Opțional: dă-le prin nucă de cocos sau nuci măcinate."], benefits:["Morcovii oferă beta-caroten, benefic pentru piele și ochi","Condimentele calde au proprietăți antiinflamatorii","Îndulcite natural, doar cu fruct întreg"], tip:"Adaugă un strop de suc de portocală în amestec pentru o notă citrică de tip carrot cake." },
  ds033: { name:"Cupe cheesecake raw cu afine", steps:["Bază: mixează curmalele și migdalele până devin o crumbă lipicioasă. Presează în forme de brioșe.","Umplutură: mixează caju, ulei de cocos, lămâie și miere până obții o cremă fină.","Mixează afinele separat, până obții un piure.","Amestecă în valuri crema de caju cu piureul de afine în forme. Congelează 2 ore."], benefits:["Afinele se numără printre alimentele cu cel mai ridicat conținut de antioxidanți","Caju oferă vitamine din grupul B și grăsimi sănătoase","Fără zahăr rafinat și fără lactate"], tip:"Presează bine baza pentru a nu se sfărâma la scoaterea din formă." },
  ds034: { name:"Batoane cu caramel sărat și pecan", steps:["Mixează curmalele, tahini, uleiul de cocos și vanilia până obții o pastă fină de caramel.","Presează făina de migdale și jumătate din pecan într-o tavă de 20cm tapetată, pentru bază.","Întinde caramelul de curmale peste bază.","Presează pecanul rămas deasupra. Presară sare de mare. Congelează 1 oră înainte de a tăia."], benefits:["Pecanul este bogat în zinc, mangan și gamma-tocoferol (vitamina E)","Tahini adaugă calciu și sesamină, cu efect antiinflamator","Sarea accentuează gustul de caramel natural, fără zahăr"], tip:"Taie cu un cuțit cald pentru margini curate ale batoanelor." },
  ds035: { name:"Trufe de cacao cu portocală", steps:["Mixează curmalele, cacaua, făina de migdale, coaja de portocală și uleiul de cocos până se formează un aluat.","Formează 14 bile. Congelează 15 minute.","Scufundă fiecare bilă în ciocolată neagră topită. Lasă să se întărească pe hârtie de copt."], benefits:["Coaja de portocală conține d-limonen, un compus puternic de detoxifiere","Cacaua și citricele se completează reciproc prin profilul lor antioxidant","O combinație clasică de arome, într-o variantă sănătoasă"], tip:"Adaugă un vârf de cuțit de cayenne pentru o variantă de ciocolată mexicană." },
  ds036: { name:"Bomboane de cocos cu lime", steps:["Amestecă toate ingredientele într-un bol, până se formează un aluat gros.","Ține la frigider 20 de minute, să se întărească.","Formează 12 bile. Dă-le prin nucă de cocos rasă.","Păstrează la frigider până la 1 săptămână."], benefits:["Lime oferă vitamina C și acid citric, util pentru detoxifiere","MCT-urile din cocos sunt folosite rapid ca energie","Profil aromatic proaspăt și răcoritor"], tip:"Folosește nucă de cocos rumenită pe exterior pentru mai multă profunzime de gust." },
  ds037: { name:"Batoane cu căpșuni și nucă de cocos", steps:["Mărunțește nuca de cocos cu caju, jumătate din miere și uleiul de cocos, până devine sfărâmicioasă. Presează într-o tavă tapetată.","Mixează căpșunile cu mierea rămasă și vanilia, până se omogenizează.","Toarnă peste bază. Congelează 2 ore, până se întărește.","Taie în batoane și servește rece."], benefits:["Căpșunile sunt bogate în vitamina C și acid elagic","Caju oferă magneziu și grăsimi sănătoase","Culoare roz vibrantă, din fruct natural"], tip:"Decorează cu felii proaspete de căpșuni pentru un aspect frumos." },
  ds038: { name:"Cupe praline de alune", steps:["Mixează alunele prăjite până formează un unt grosier.","Adaugă curmalele și cacaua. Mixează până obții o pastă.","Presează în forme de silicon pentru brioșe.","Topește ciocolata cu crema de cocos. Toarnă peste baza de alune. Presară sare.","Congelează 1,5 ore. Scoate din formă și servește."], benefits:["Alunele sunt excepțional de bogate în vitamina E, benefică pentru piele","Amintește natural de un Ferrero Rocher mai sănătos","Prăjirea intensifică aroma de alune fără ingrediente în plus"], tip:"Prăjește alunele la 180°C timp de 8-10 minute, până crapă coaja — freacă-le cu un prosop pentru o aromă mai curată." },
  ds007: { name:"Înghețată de banane cu 3 ingrediente", steps:["Curăță și congelează bananele peste noapte, până se întăresc.","Mixează bucățile de banană congelată până devin fine și cremoase — răzuiește marginile din când în când.","Adaugă untul de arahide și vanilia, mixează scurt.","Servește imediat, ca înghețată moale, sau congelează 1 oră pentru o consistență mai fermă."], benefits:["Bananele coapte sunt bogate în potasiu și prebiotice naturale","Nu conține lactate, zahăr rafinat sau aditivi artificiali","Sursă rapidă de energie naturală, ideală după antrenament"], tip:"Mixează mango sau căpșuni congelate pentru arome diferite. Presară miez de cacao pentru crocanță." },
  ds008: { name:"Înghețată pe băț cu mango și cocos", steps:["Mixează mango, laptele de cocos, zeama de lime și mierea, până devin complet fine.","Toarnă în forme de înghețată pe băț, presară fulgi de cocos deasupra.","Înfige bețele și congelează minimum 4 ore.","Trece formele scurt sub apă caldă pentru a le scoate mai ușor."], benefits:["Mango este excepțional de bogat în vitamina C și folat","Laptele de cocos oferă trigliceride cu lanț mediu, pentru energie rapidă","Fără lactate, perfect pentru zilele călduroase"], tip:"Alternează două straturi — de mango și de cocos — pentru un efect vizual în două culori." },
  ds009: { name:"Crocant înghețat de iaurt cu fructe de pădure", steps:["Amestecă iaurtul, mierea și vanilia, până devin fine.","Întinde uniform, într-un strat de 1cm, pe o tavă de copt tapetată.","Presară fructele de pădure și granola deasupra, apăsând ușor.","Congelează 3-4 ore, până se întărește. Sparge în bucăți și servește imediat."], benefits:["Iaurtul grecesc oferă 6g de proteine per porție, plus probiotice benefice pentru intestin","Fructele de pădure se numără printre alimentele cu cel mai ridicat conținut de antioxidanți","Puține calorii și dens nutrițional"], tip:"Prepară-l duminică pentru o săptămână întreagă de desert sănătos — păstrat într-o pungă de congelator." },
  ds010: { name:"Granită de pepene roșu și mentă", steps:["Mixează pepenele, lime-ul, menta și mierea, până devin fine.","Toarnă într-un vas larg și plat, potrivit pentru congelator.","Congelează 1 oră, apoi răzuiește cu o furculiță la fiecare 30 de minute, timp de 3 ore.","Servește afânată, în pahare sau boluri."], benefits:["Pepenele roșu conține 92% apă, ideal pentru hidratare","Conține licopen, un antioxidant puternic, asociat cu sănătatea inimii","Doar 55 kcal per porție — ideal pentru controlul greutății"], tip:"Adaugă un strop de apă de cocos în loc de apă simplă, pentru electroliți în plus." },
  ds011: { name:"Înghețată pe băț cu ciocolată și cocos", steps:["Încălzește laptele de cocos într-o cratiță, la foc mic.","Adaugă ciocolata și amestecă până se topește. Ia de pe foc.","Amestecă cu telul pudra de cacao, siropul de arțar și vanilia.","Lasă să se răcorească puțin, toarnă în forme și congelează peste noapte."], benefits:["MCT-urile din laptele de cocos susțin energia constantă","Bogat în antioxidanți, din ciocolata neagră","Alternativă fără lactate la înghețata clasică"], tip:"Adaugă o lingură de unt de migdale pentru mai multă cremozitate și proteine." },
  ds012: { name:"Sorbet înghețat de acai", steps:["Sparge pachetele de acai congelat în bucăți.","Mixează acai, banana și fructele de pădure, până devine gros și fin, ca un sorbet.","Îndulcește cu miere, după gust.","Servește imediat, în boluri reci, cu toppinguri după preferință."], benefits:["Acai este unul dintre cele mai bogate alimente în antioxidanți din lume","Bogat în antociani, asociați cu îmbunătățirea sănătății creierului","Fibrele multe susțin sănătatea digestivă"], tip:"Adaugă granola, felii de banană și un fir de miere, pentru un adevărat acai bowl." },
  ds039: { name:"Înghețată pe băț cu piersici și cremă", steps:["Mixează piersicile, mierea și lămâia, până devin fine.","Amestecă separat iaurtul cu vanilia.","Alternează în straturi piureul de fructe și iaurtul, în forme.","Înfige bețele, congelează minimum 4 ore."], benefits:["Piersicile sunt bogate în beta-caroten și vitamina C","Iaurtul grecesc adaugă proteine și probiotice","Sub 85 kcal per bucată"], tip:"Piersicile coapte și parfumate fac toată diferența — folosește-le în sezonul lor de vârf." },
  ds040: { name:"Sorbet de kiwi și lime", steps:["Mixează toate ingredientele până devin complet fine.","Congelează într-un vas puțin adânc timp de 1 oră, apoi răzuiește.","Repetă răzuirea la fiecare 30 de minute, timp de 2-3 ore.","Servește în boluri reci, cu o crenguță de mentă."], benefits:["Kiwi are mai multă vitamina C per gram decât portocalele","Bogat în vitamina K, benefică pentru sănătatea oaselor","Puține calorii și hidratant"], tip:"Kiwi auriu dă o variantă mai dulce și mai puțin acrișoară a acestui sorbet." },
  ds041: { name:"Înghețată de banane cu afine", steps:["Mixează bananele și afinele congelate până încep să se lege.","Adaugă laptele de migdale și vanilia, mixează până devine fin și gros.","Servește imediat, ca înghețată moale, sau congelează 45 de minute pentru o textură care se poate servi cu lingura de înghețată.","Presară fructe de pădure proaspete sau granola deasupra."], benefits:["Afinele oferă antociani, benefici pentru sănătatea creierului și a inimii","Bananele adaugă potasiu și dulceață naturală","Zero zahăr rafinat, fără lactate — desert din alimente integrale"], tip:"Raportul dintre banană congelată și afine controlează dulceața — ajustează după gust." },
  ds042: { name:"Batoane înghețate cu cireșe și ciocolată", steps:["Mixează cireșele, laptele de cocos, cacaua, siropul de arțar și vanilia, până devin fine.","Toarnă într-o tavă de chec de 20x10cm tapetată sau în forme pentru batoane.","Congelează minimum 4 ore, până se întăresc.","Taie și servește imediat, sau păstrează bucățile individual într-o pungă cu fermoar."], benefits:["Cireșele sunt bogate în melatonină, care susține ciclurile naturale de somn","Antocianii din cireșe reduc durerile musculare de după exercițiu","Combinația ciocolată-cireșe este bogată în polifenoli"], tip:"Folosește vișine pentru o aromă mai intensă, mai puțin dulce, care se potrivește perfect cu ciocolata neagră." },
  ds043: { name:"Înghețată pe băț cu limonadă de căpșuni", steps:["Mixează toate ingredientele până devin fine.","Gustă și ajustează dulceața cu miere.","Toarnă în forme de înghețată pe băț.","Congelează minimum 5 ore sau peste noapte."], benefits:["Căpșunile au un conținut foarte ridicat de vitamina C și antioxidanți","Doar 48 kcal per bucată","Răcoritoare și hidratante, în zilele calde"], tip:"Adaugă un strop de apă de trandafiri pentru o notă elegantă." },
  ds044: { name:"Înghețată de matcha și cocos", steps:["Amestecă matcha cu 2 linguri de lapte de cocos călduț, până devine o pastă fină.","Mixează cu restul de lapte de cocos, mierea, vanilia și sarea.","Ține amestecul la frigider 2 ore, apoi mixează-l în aparatul de înghețată, SAU congelează 3 ore, amestecând la fiecare 45 de minute.","Servește în boluri reci."], benefits:["Matcha oferă energie constantă și L-teanină, pentru o concentrare calmă","Fără lactate și vegan","Catechinele din ceaiul verde susțin metabolismul"], tip:"Răcirea amestecului înainte de congelare dă o textură mai fină." },
  ds013: { name:"Briose cu banane și făină de migdale", steps:["Preîncălzește cuptorul la 180°C. Tapetează o tavă pentru 12 brioșe.","Amestecă cu telul ouăle, banana pisată, mierea și vanilia.","Adaugă făina de migdale, bicarbonatul de sodiu și scorțișoara, amestecând până se combină.","Încorporează fulgii de ciocolată. Împarte compoziția în formele de brioșe.","Coace 20-22 de minute, până când o scobitoare iese curată."], benefits:["Făina de migdale oferă mai multe proteine și mai puțini carbohidrați decât făina de grâu","Îndulcite natural, cu banane coapte și puțină miere","Fără gluten și fără cereale"], tip:"Congelează briosele coapte până la 2 luni. Reîncălzește 30 de secunde, direct din congelator." },
  ds014: { name:"Batoane de ovăz cu miere", steps:["Preîncălzește cuptorul la 175°C. Tapetează o tavă pătrată de 20cm.","Topește uleiul de cocos și mierea împreună, la foc mic.","Adaugă fulgii de ovăz, semințele, merișoarele uscate și scorțișoara. Amestecă bine.","Presează ferm în tavă. Coace 18-20 de minute, până se rumenește.","Lasă să se răcească complet înainte de a tăia în 12 batoane."], benefits:["Ovăzul oferă fibre beta-glucan, care ajută la scăderea colesterolului","Semințele adaugă zinc, magneziu și acizi grași omega-3","Eliberare susținută de energie — ideal înainte sau după antrenament"], tip:"Presează amestecul ferm în tavă, înainte de coacere, pentru batoane care se țin bine." },
  ds015: { name:"Macaroons de cocos", steps:["Preîncălzește cuptorul la 165°C. Tapetează o tavă de copt.","Bate ușor albușurile cu mierea, vanilia și esența de migdale.","Încorporează nuca de cocos rasă, până se acoperă uniform.","Formează grămăjoare cu lingura, pe tavă. Coace 15-18 minute, până se rumenesc.","Lasă să se răcească complet. Scufundă bazele în ciocolată topită, dacă dorești."], benefits:["Nuca de cocos oferă trigliceride cu lanț mediu, pentru energie","Mai puțini carbohidrați decât biscuiții tradiționali","Natural fără gluten și fără lactate"], tip:"Coace-le puțin mai puțin pentru un centru moale — se întăresc pe măsură ce se răcesc." },
  ds016: { name:"Fursecuri de ovăz cu unt de arahide", steps:["Preîncălzește cuptorul la 180°C.","Amestecă untul de arahide, banana pisată și mierea, până se omogenizează.","Încorporează fulgii de ovăz, fulgii de ciocolată și sarea.","Formează grămăjoare pe tava de copt. Aplatizează ușor. Coace 12-14 minute.","Lasă-le pe tavă la răcit — se întăresc pe măsură ce se răcesc."], benefits:["Untul de arahide oferă proteine și niacină, utile pentru metabolism","Banana îndulcește natural, fără zahăr adăugat","Bază din 3 ingrediente — infinit de adaptabilă"], tip:"Presară puțină sare de mare deasupra, înainte de coacere, pentru o aromă de tip caramel sărat." },
  ds017: { name:"Brownies cu curmale și tahini", steps:["Preîncălzește cuptorul la 175°C. Tapetează o tavă pătrată de 20cm.","Mixează curmalele până obții o pastă fină.","Amestecă cu telul tahini, ouăle și vanilia.","Încorporează cacaua, praful de copt și sarea, până se combină.","Coace 18-22 de minute — centrul trebuie să rămână puțin moale.","Lasă să se răcească complet înainte de a tăia."], benefits:["Tahini oferă calciu și lignani de susan, cu efect antiinflamator","Curmalele înlocuiesc zahărul rafinat cu fibre și minerale","Fără gluten și fără cereale"], tip:"Adaugă deasupra o glazură de cacao cu susan, pentru o notă inspirată din bucătăria Orientului Mijlociu." },
  ds018: { name:"Brownies cu fasole neagră", steps:["Preîncălzește cuptorul la 175°C. Unge o tavă pătrată de 20cm.","Mixează fasolea neagră până devine fină.","Adaugă ouăle, cacaua, mierea, uleiul și vanilia — mixează până devine mătăsos.","Încorporează praful de copt și fulgii de ciocolată.","Toarnă în tavă. Coace 22-25 de minute.","Lasă să se răcească complet înainte de a tăia."], benefits:["Fasolea neagră adaugă 6g de proteine și 3,5g de fibre per bucată","Fără făină — fără gluten și cu grad ridicat de sațietate","Fasolea oferă amidon rezistent, benefic pentru microbiomul intestinal"], tip:"Nimeni nu va ghici că sunt fasole înăuntru — gustul este de ciocolată pură." },
  ds019: { name:"Crumble de piersici cu migdale", steps:["Preîncălzește cuptorul la 190°C.","Amestecă piersicile cu jumătate din miere și scorțișoara. Pune-le într-un vas de copt.","Freacă între degete făina de migdale, fulgii de ovăz, uleiul de cocos și mierea rămasă, pentru o textură de crumble.","Amestecă migdalele fulgi. Presară uniform peste piersici.","Coace 25-30 de minute, până clocotește și se rumenește."], benefits:["Piersicile sunt bogate în vitaminele C, A și potasiu","Crumble-ul din făină de migdale adaugă proteine și vitamina E","Natural fără gluten, cu ingrediente hrănitoare"], tip:"Servește cald, cu o lingură de iaurt de cocos sau puțină înghețată de banane." },
  ds020: { name:"Mere coapte cu scorțișoară", steps:["Preîncălzește cuptorul la 180°C.","Scobește merele, lăsând baza intactă. Pune-le într-un vas de copt cu ½ cană de apă.","Amestecă fulgii de ovăz, nucile, mierea, uleiul, scorțișoara și stafidele.","Umple cavitățile merelor cu amestecul de ovăz.","Coace 25-30 de minute, până merele devin fragede. Servește cald."], benefits:["Merele oferă pectină, o fibră care hrănește bacteriile benefice din intestin","Scorțișoara ajută la reglarea vârfurilor de glicemie după masă","Conținutul ridicat de fibre le face surprinzător de sățioase"], tip:"Folosește mere Braeburn sau Cox pentru cea mai bună textură — își păstrează forma la copt." },
  ds045: { name:"Brownies cu cartof dulce", steps:["Preîncălzește cuptorul la 180°C. Tapetează o tavă de 20cm.","Amestecă cu telul cartoful dulce, untul de migdale, mierea și ouăle, până devine fin.","Încorporează cacaua, praful de copt și vanilia.","Toarnă în tavă. Coace 22-25 de minute — centrul trebuie să fie abia închegat.","Lasă să se răcească complet înainte de a tăia."], benefits:["Cartoful dulce adaugă beta-caroten și fibre, discret","Fără gluten, fără cereale și dens nutrițional","Untul de migdale oferă proteine și vitamina E"], tip:"Cu cât brownies-urile sunt mai fondante la scoaterea din cuptor, cu atât mai bine — se întăresc pe măsură ce se răcesc." },
  ds046: { name:"Tort de ciocolată cu dovlecel", steps:["Preîncălzește cuptorul la 175°C. Unge o tavă rotundă de 20cm.","Stoarce excesul de apă din dovlecelul ras.","Amestecă cu telul ouăle, siropul de arțar și uleiul de cocos.","Încorporează făina de migdale, cacaua și bicarbonatul de sodiu.","Adaugă dovlecelul.","Coace 28-32 de minute. Lasă la răcit înainte de a tăia."], benefits:["Dovlecelul adaugă umiditate și nutrienți, discret","Mai multe proteine și indice glicemic mai mic decât un tort obișnuit","Fără gluten și fără cereale"], tip:"Acoperă cu un strat subțire de ganache de ciocolată neagră, pentru o prezentare rafinată." },
  ds047: { name:"Briose cu lămâie și semințe de mac", steps:["Preîncălzește cuptorul la 175°C. Tapetează o tavă pentru 12 brioșe.","Amestecă cu telul ouăle, mierea, uleiul de cocos, coaja și zeama de lămâie.","Încorporează făina de migdale, bicarbonatul de sodiu și semințele de mac.","Împarte în forme. Coace 18-20 de minute, până se rumenesc.","Lasă la răcit înainte de servire."], benefits:["Aromă vie de citrice, fără esențe artificiale","Făina de migdale le face fără cereale și bogate în proteine","Semințele de mac sunt o sursă bună de calciu și mangan"], tip:"Toarnă deasupra o glazură subțire de lămâie cu miere, cât încă sunt calde, pentru mai multă umiditate." },
  ds048: { name:"Chec de morcovi cu nuci", steps:["Preîncălzește cuptorul la 175°C. Tapetează o tavă de chec.","Amestecă cu telul ouăle, siropul de arțar și uleiul de cocos.","Încorporează făina de migdale, scorțișoara și praful de copt.","Adaugă morcovii și nucile.","Coace 40-45 de minute, până când o scobitoare iese curată. Lasă la răcit înainte de a tăia."], benefits:["Nucile oferă grăsimi omega-3 și precursori ai melatoninei","Morcovii adaugă beta-caroten și dulceață naturală","Fără gluten și fără cereale"], tip:"Se păstrează bine la frigider 4 zile, sau congelează felii individuale." },
  ds049: { name:"Tort de hrișcă cu miere", steps:["Preîncălzește cuptorul la 175°C. Unge o tavă rotundă de 20cm.","Amestecă cu telul ouăle, mierea, uleiul de cocos și laptele de migdale.","Încorporează făina de hrișcă, scorțișoara și praful de copt.","Coace 28-32 de minute, până se leagă. Lasă la răcit înainte de a servi."], benefits:["Hrișca este natural fără gluten și bogată în rutină, benefică pentru vasele de sânge","Indice glicemic mai mic decât făina de grâu","Aroma de alune se potrivește minunat cu mierea"], tip:"Pudrează cu făină de hrișcă și servește cu fructe proaspete, pentru o prezentare elegantă." },
  ds050: { name:"Batoane crumble cu fructe de pădure", steps:["Preîncălzește cuptorul la 180°C. Tapetează o tavă de 20x30cm.","Amestecă fulgii de ovăz, făina de migdale, uleiul de cocos, mierea și scorțișoara.","Presează ⅔ din amestecul de ovăz în tavă.","Amestecă fructele de pădure cu semințele de chia și întinde peste bază.","Sfărâmă restul amestecului de ovăz deasupra.","Coace 28-32 de minute, până se rumenește. Lasă la răcit înainte de a tăia."], benefits:["Beta-glucanul din ovăz reduce colesterolul LDL","Fructele de pădure adaugă antioxidanți concentrați și vitamina C","Semințele de chia ajută stratul de fructe să se lege natural"], tip:"Dă la frigider înainte de a tăia, pentru margini curate ale batoanelor." },
  ds021: { name:"Mousse de ciocolată cu avocado", steps:["Taie avocado în jumătate, scoate sâmburele și pune pulpa în blender.","Adaugă toate celelalte ingrediente.","Mixează până devine complet fin și lucios — 2-3 minute.","Gustă și ajustează dulceața.","Dă la frigider 30 de minute. Servește în pahare, cu fructe de pădure deasupra."], benefits:["Avocado oferă glutation, antioxidantul principal al organismului","Grăsimile mononesaturate susțin producția de hormoni","Cremos, fără lactate — potrivit pentru vegani"], tip:"Mousse-ul se păstrează 24 de ore la frigider, cu folie alimentară lipită direct pe suprafață." },
  ds022: { name:"Budincă de chia cu mango", steps:["Amestecă semințele de chia, laptele de cocos și mierea. Amestecă bine.","Dă la frigider minimum 2 ore (sau peste noapte), amestecând o dată după 30 de minute.","Mixează mango cu coaja de lime, până obții un piure fin.","Așază în straturi budinca de chia și piureul de mango, în pahare.","Decorează cu cuburi de mango în plus și mentă."], benefits:["Semințele de chia oferă 8g de fibre per porție — excepțional pentru sănătatea intestinală","Sursă completă de omega-3 din plante","Mango oferă vitamina C, vitamina A și folat"], tip:"Prepară cu o seară înainte, pentru un desert-mic dejun perfect, gata de luat cu tine." },
  ds023: { name:"Panna cotta de cocos și vanilie", steps:["Dizolvă gelatina în 3 linguri de apă rece; lasă 5 minute.","Încălzește laptele de cocos cu mierea și vanilia, la foc mediu, până începe să aburească — nu lăsa să dea în clocot.","Amestecă cu telul gelatina dizolvată, până se încorporează complet.","Toarnă în 4 forme sau pahare. Dă la frigider 4 ore, până se întărește.","Servește cu sos de fructe de pădure deasupra."], benefits:["Laptele de cocos este natural fără lactate, cu textură cremoasă și bogată","MCT-urile din laptele de cocos susțin funcția cognitivă","Desert elegant, de calitate de restaurant, cu doar 5 ingrediente"], tip:"Folosește agar-agar în loc de gelatină pentru o variantă complet vegană — ajustează cantitatea conform indicațiilor de pe ambalaj." },
  ds024: { name:"Fool de zmeură și chia", steps:["Zdrobește jumătate din zmeură cu mierea, pentru un sos rustic.","Amestecă semințele de chia în iaurtul grecesc, cu vanilia. Lasă 15 minute să se îngroașe.","Așază în straturi amestecul de iaurt și sosul de zmeură, în pahare.","Decorează cu zmeură întreagă și un fir de miere."], benefits:["Zmeura conține mai multe fibre decât aproape orice alt fruct","Iaurtul grecesc aduce 7g de proteine și culturi probiotice vii","Sub 120 kcal per porție"], tip:"Înlocuiește zmeura cu căpșuni sau fructe de pădure de vară, în funcție de sezon." },
  ds025: { name:"Orez cu lapte, turmeric și miere (Golden Milk)", steps:["Pune orezul, laptele de cocos și laptele de migdale într-o cratiță.","Fierbe la foc mic-mediu, amestecând des, timp de 30 de minute, până orezul devine fraged.","Amestecă mierea, turmericul, scorțișoara, cardamomul și piperul negru.","Servește cald, în boluri, cu un fir de miere deasupra și scorțișoară presărată."], benefits:["Curcumina din turmeric este un compus antiinflamator puternic","Piperul negru mărește absorbția curcuminei cu până la 2000%","Cald și liniștitor — util mai ales în lunile reci"], tip:"Prepară o cantitate mai mare și reîncălzește porții individuale cu un strop de lapte de migdale, pe parcursul săptămânii." },
  ds051: { name:"Mousse de ciocolată neagră cu portocală", steps:["Scoate doar partea solidă a cremei de cocos dintr-o cutie ținută la frigider peste noapte (aruncă lichidul).","Bate crema de cocos cu mixerul electric, până devine pufoasă.","Topește ciocolata și las-o să se răcorească puțin. Încorporeaz-o în cremă, împreună cu mierea, coaja de portocală și vanilia.","Toarnă în pahare cu lingura. Dă la frigider 1 oră înainte de servire."], benefits:["Ciocolata neagră 85% este bogată în magneziu și flavanoli","Coaja de portocală adaugă vitamina C și aromă naturală, fără zahăr","Fără lactate și fin, mătăsos la gust"], tip:"Secretul este crema de cocos bine răcită — ține cutia la frigider peste noapte pentru cele mai bune rezultate." },
  ds052: { name:"Budincă de căpșuni și banane", steps:["Mixează bananele, căpșunile și laptele de cocos, până devin fine.","Amestecă semințele de chia și vanilia.","Dă la frigider minimum 2 ore sau peste noapte, până devine groasă, ca o budincă.","Servește cu felii de căpșuni deasupra."], benefits:["Semințele de chia oferă omega-3 și 6g de fibre per porție","Natural dulce — zero zahăr rafinat","Bogată în vitamina C, din căpșuni"], tip:"Folosește banane ceva mai coapte, pentru dulceață și cremozitate maxime." },
  ds053: { name:"Cremă de vanilie cu migdale", steps:["Amestecă cu telul gălbenușurile, mierea și amidonul de porumb.","Încălzește laptele de migdale până începe să aburească. Toarnă treptat peste amestecul de ouă, amestecând continuu.","Pune înapoi în cratiță, la foc mediu, amestecând constant, până se îngroașă.","Adaugă vanilia și esența de migdale. Toarnă în boluri.","Servește caldă sau rece."], benefits:["Fără lactate, dar tot cremoasă și bogată","Gălbenușurile oferă colină, benefică pentru sănătatea creierului","Reconfortantă și cu mai puține calorii decât o cremă tradițională"], tip:"Pune folie alimentară direct pe suprafață, imediat, pentru a evita formarea unei pelicule pe măsură ce se răcește." },
  ds026: { name:"Bile energizante de matcha și cocos", steps:["Mixează caju până se macină fin.","Adaugă curmalele, nuca de cocos, matcha și mierea. Mixează până se formează un aluat lipicios.","Formează 12 bile cu mâinile umede.","Dă-le prin fulgi de cocos. Ține la frigider 20 de minute înainte de servire."], benefits:["Matcha oferă energie susținută, prin L-teanină, fără nervozitate","L-teanina promovează o concentrare calmă, alături de cafeina naturală","Ceai verde bogat în antioxidanți, într-un format portabil"], tip:"Folosește matcha de calitate ceremonială pentru o culoare mai vie și o aromă mai fină." },
  ds027: { name:"Bomboane energizante cu lămâie și chia", steps:["Combină toate ingredientele, în afară de nuca de cocos pentru acoperire, într-un bol mare.","Amestecă bine, până totul se leagă.","Dă la frigider 20 de minute, să se întărească.","Formează 14 bile. Dă-le prin nucă de cocos rasă.","Păstrează la frigider până la 1 săptămână."], benefits:["Coaja de lămâie conține d-limonen, un compus puternic de detoxifiere","Semințele de chia se dilată în intestin, pentru sațietate prelungită","Conținut ridicat de magneziu, din ovăz și unt de migdale"], tip:"Ținerea amestecului la frigider înainte de a-l modela previne lipirea de mâini și dă o bilă mai îngrijită." },
  ds028: { name:"Bomboane de fistic cu apă de trandafiri", steps:["Mărunțește fisticul în robotul de bucătărie, până se macină fin, păstrând puțină textură.","Adaugă curmalele, apa de trandafiri, cardamomul și mierea. Mixează până devine lipicios.","Formează 12 bile. Dă-le prin firimituri de fistic zdrobit.","Ține la frigider minimum 30 de minute înainte de servire."], benefits:["Fisticul este printre nucile cu cel mai ridicat conținut de proteine","Apa de trandafiri este folosită în medicina persană pentru dispoziție și digestie","Bogat în luteină și zeaxantină, benefice pentru sănătatea ochilor"], tip:"Sunt inspirate din dulciurile persane — arată frumos pe o tavă de desert, la ocazii speciale." },
  ds029: { name:"Bile de fericire cu caju și turmeric", steps:["Mixează caju până se macină fin.","Adaugă curmalele, turmericul, piperul negru, uleiul de cocos și mierea. Mixează până se formează un aluat.","Dă la frigider 15 minute.","Formează 12 bile. Dă-le prin fulgi de cocos.","Păstrează la frigider până la 10 zile."], benefits:["Curcumina din turmeric are efecte antiinflamatorii puternice","Piperul negru mărește semnificativ biodisponibilitatea curcuminei","Caju oferă cupru și magneziu"], tip:"Sunt deosebit de potrivite iarna sau în perioadele de refacere, datorită proprietăților antiinflamatorii." },
  ds054: { name:"Bomboane de migdale cu espresso", steps:["Mărunțește migdalele până se toacă fin.","Adaugă curmalele, espresso-ul, cacaua, untul de migdale și sarea. Procesează până se formează un aluat lipicios.","Formează 12 bile.","Ține la frigider minimum 20 de minute înainte de servire."], benefits:["Energie naturală pre-antrenament, din curmale și espresso","Migdalele oferă energie susținută și vitamina E","Aromă bogată de moka, fără ingrediente procesate"], tip:"Folosește pudră de espresso decafeinizat pentru o gustare de seară, fără cofeină." },
  ds055: { name:"Bile cu scorțișoară și stafide", steps:["Amestecă toate ingredientele într-un bol, până se combină bine.","Dă la frigider 15 minute, să se întărească.","Formează 12 bile.","Păstrează într-un recipient etanș, la frigider, până la 1 săptămână."], benefits:["Aromă clasică, condimentată, care amintește de o fursec cu ovăz","Stafidele oferă fier natural și energie cu eliberare rapidă","Gustare bună de mijloc de dimineață sau înainte de antrenament"], tip:"Înmoaie stafidele în apă caldă timp de 10 minute înainte de utilizare, pentru un rezultat mai pufos și mai suculent." },
  ds056: { name:"Bile proteice cu semințe de cânepă", steps:["Combină semințele de cânepă, fulgii de ovăz, untul de migdale, mierea și vanilia.","Amestecă până se formează un aluat lipicios. Dă la frigider 15 minute.","Formează 12 bile. Dă-le prin semințe de cânepă suplimentare.","Păstrează la frigider până la 1 săptămână."], benefits:["Semințele de cânepă sunt o proteină completă, cu toți aminoacizii esențiali","Bogate în omega-3 și omega-6, într-un raport ideal de 3:1","Una dintre cele mai bune gustări proteice din plante disponibile"], tip:"Adaugă o lingură de spirulină pentru un plus de proteine vegetale și micronutrienți." },
  ds057: { name:"Bomboane de ciocolată cu unt de arahide", steps:["Amestecă untul de arahide, mierea și vanilia.","Încorporează fulgii de ovăz, cacaua și fulgii de ciocolată.","Dă amestecul la frigider 20 de minute.","Formează 14 bile. Păstrează la frigider."], benefits:["Untul de arahide oferă niacină, folat și proteine","Aromă clasică, de tip Reese's, într-un format din alimente integrale","Conținut ridicat de magneziu, din cacao"], tip:"Congelează 30 de minute pentru o textură mai fermă, ca de fudge." },
  ds058: { name:"Bile de caise cu semințe de floarea-soarelui", steps:["Mărunțește semințele de floarea-soarelui până se macină fin.","Adaugă caisele, nuca de cocos, mierea și cardamomul. Procesează până devine lipicios.","Formează 14 bile. Dă-le prin nucă de cocos în plus.","Ține la frigider 20 de minute înainte de servire."], benefits:["Caisele sunt bogate în beta-caroten și fier natural","Semințele de floarea-soarelui sunt excepțional de bogate în vitamina E","Cardamomul susține sănătatea digestivă"], tip:"Caută caise nesulfitate — sunt maro, nu portocaliu-aprins, și nu conțin conservanți." },
  ds030: { name:"Banane caramelizate cu crumble de nuci", steps:["Taie bananele pe lungime, în jumătate.","Încălzește uleiul de cocos într-o tigaie, la foc mediu-mare.","Așază bananele cu partea tăiată în jos; gătește 2-3 minute, până se rumenesc.","Toarnă mierea și presară scorțișoară. Întoarce și gătește încă 1 minut.","Servește cu nuci tocate și fulgi de ciocolată presărați deasupra."], benefits:["Bananele caramelizate sunt bogate în potasiu și vitamina B6","Nucile adaugă grăsimi omega-3 și creează o crocanță plăcută","Desert rapid, cald, gata în mai puțin de 15 minute"], tip:"Servește cu iaurt de cocos pentru un desert complet, care se simte totuși ca o răsfățare." },
  ds031: { name:"Smochine coapte cu miere și iaurt", steps:["Preîncălzește cuptorul la 200°C.","Așază jumătățile de smochine cu partea tăiată în sus, într-un vas de copt.","Toarnă mierea deasupra și așază crenguțe de cimbru printre ele.","Coace 12-15 minute, până smochinele devin fragede și caramelizate.","Servește peste iaurt grecesc, cu nuci deasupra."], benefits:["Smochinele sunt remarcabile prin conținutul de calciu și fier, printre fructele proaspete","Cimbrul are proprietăți antimicrobiene și susține sănătatea respiratorie","Elegant, sezonier și natural dulce"], tip:"Smochinele proaspete sunt cele mai bune la sfârșit de vară. În afara sezonului, folosește smochine uscate, înmuiate în apă caldă." },
  ds032: { name:"Pere coapte cu scorțișoară", steps:["Preîncălzește cuptorul la 190°C.","Taie și scobește perele. Așază-le cu partea tăiată în sus, într-un vas de copt.","Toarnă mierea, lămâia și vanilia. Presară scorțișoară.","Adaugă 4 linguri de apă în vas. Coace 20-25 de minute, până devin fragede și rumenite.","Servește calde, cu granola și iaurt."], benefits:["Perele au unul dintre cele mai ridicate conținuturi de fibre dintre fructele obișnuite","Doar 90 kcal per porție — ușor și sățios","Scorțișoara ajută la reglarea glicemiei după masă"], tip:"Folosește pere Conference sau Williams — își păstrează frumos forma la copt." },
  ds059: { name:"Ananas la grătar cu cremă de cocos", steps:["Încălzește o tigaie grill la foc mare.","Unge feliile de ananas cu miere și scorțișoară.","Prăjește 2-3 minute pe fiecare parte, până se caramelizează și se rumenesc.","Bate crema de cocos cu un vârf de scorțișoară.","Servește ananasul cald cu cremă de cocos și mentă proaspătă."], benefits:["Ananasul conține bromelaină, o enzimă digestivă puternică, cu efect antiinflamator","Prăjirea concentrează zaharurile naturale și intensifică aroma","Doar 112 kcal — un desert de vară, ușor"], tip:"Adaugă un strop de lime și un vârf de fulgi de chili pentru o notă tropicală picantă." },
  ds060: { name:"Compot de rubarbă și căpșuni", steps:["Pune rubarba, mierea și zeama de portocală într-o cratiță.","Gătește la foc mediu 8-10 minute, până rubarba se înmoaie.","Adaugă căpșunile și mai gătește 3 minute.","Ia de pe foc, adaugă vanilia.","Servește cald, peste iaurt sau înghețată de banane."], benefits:["Rubarba are un conținut foarte ridicat de vitamina K, benefică pentru oase","Doar 72 kcal per porție — foarte ușor","Bogat în vitamina C și antioxidanți, din căpșuni"], tip:"E delicios rece, direct din frigider, a doua zi — aromele se leagă și se adâncesc peste noapte." },
  ds061: { name:"Salată de citrice cu miere", steps:["Așază feliile de citrice pe un platou de servire.","Toarnă mierea deasupra.","Presară frunze de mentă și semințe de rodie.","Servește imediat sau ține la frigider până la 2 ore."], benefits:["Una dintre cele mai mari porții de vitamina C posibile dintr-un desert","Semințele de rodie adaugă antioxidanți de tip punicalagine","Sub 80 kcal — foarte puține calorii"], tip:"Servește alături de un desert cu ciocolată, pentru un contrast răcoritor." },
  ds062: { name:"Prune coapte cu vanilie", steps:["Preîncălzește cuptorul la 200°C.","Așază jumătățile de prune cu partea tăiată în sus, într-un vas de copt.","Toarnă mierea, vanilia și coaja de portocală. Presară scorțișoară.","Coace 15-18 minute, până prunele devin moi și suculente.","Servește calde, cu iaurt de cocos."], benefits:["Prunele sunt bogate în sorbitol și acid neoclorogenic, benefice pentru digestie","Foarte puține calorii — doar 68 kcal","Coacerea concentrează dulceața naturală"], tip:"Folosește prune Victoria sau prune verzi (greengage), în sezon, pentru cea mai bună aromă." },
  ds063: { name:"Frigărui cu fructe tropicale", steps:["Înșiră fructele alternativ pe frigărui.","Amestecă mierea, zeama de lime și fulgii de chili (dacă folosești) într-un bol mic.","Servește la grătar sau crude, stropite cu dressingul de miere și lime.","Servește imediat."], benefits:["Vitamina C excepțională, din patru fructe tropicale","Bromelaina din ananas ajută digestia și reduce inflamația","Natural puține calorii și bogat în fibre"], tip:"Prăjește frigăruile 2 minute pe fiecare parte, pentru a caramelize zaharurile naturale, ca variantă de desert cald." },
  ds064: { name:"Pere fierte în sirop, cu ghimbir", steps:["Pune apa, mierea, ghimbirul, anasonul stelat și scorțișoara într-o cratiță.","Adu la fierbere ușoară. Cufundă perele și fierbe 20-25 de minute, până devin fragede.","Scoate perele. Reduce lichidul de fierbere la jumătate, la foc mare.","Servește perele întregi, cu siropul redus turnat deasupra."], benefits:["Elegant și îndulcit natural — perfect pentru ocazii speciale","Ghimbirul calmează digestia și reduce greața","Perele sunt excepțional de bogate în fibre și vitamina K"], tip:"Adaugă un strop de esență de vanilie de calitate în lichidul de fierbere, pentru mai multă profunzime." },
  ds065: { name:"Bol de mango cu lime", steps:["Amestecă mango tăiat cubulețe cu zeama de lime, coaja de lime și chili.","Lasă 5 minute, să se lege aromele.","Servește peste iaurt de cocos, cu mentă proaspătă deasupra."], benefits:["Mango oferă peste 100% din necesarul zilnic de vitamina C, într-un singur bol","Lime-ul și chili-ul activează enzimele digestive","Bogat în folat și vitamina A"], tip:"Folosește mango Alphonso sau Ataulfo, pentru cea mai intensă dulceață florală." },
  ds066: { name:"Cupe cu unt de arahide și banane", steps:["Tapetează o tavă de 10 mini-brioșe cu forme de hârtie.","Toarnă câte 1 linguriță de ciocolată topită în fiecare formă. Congelează 10 minute.","Amestecă untul de arahide, banana, mierea și sarea.","Toarnă umplutura peste baza de ciocolată.","Acoperă cu restul de ciocolată topită. Congelează 30 de minute."], benefits:["Variantă sănătoasă a unei cupe Reese's — fără zahăr rafinat","Banana oferă potasiu și fibre prebiotice","Untul de arahide adaugă proteine și niacină"], tip:"Presară fulgi de sare de mare deasupra, înainte ca ultimul strat de ciocolată să se întărească." },
  ds067: { name:"Pătrățele energizante cu smochine și nuci", steps:["Mixează nucile până se macină fin.","Adaugă smochinele, nuca de cocos, scorțișoara, coaja de lămâie și sarea. Mixează până devine un aluat lipicios.","Presează ferm într-o tavă pătrată de 20cm, tapetată.","Congelează 30 de minute. Taie în 16 pătrățele."], benefits:["Smochinele sunt excepțional de bogate în calciu și fier","Nucile sunt bogate în omega-3 ALA și polifenoli care protejează creierul","Coaja de lămâie adaugă vitamina C și prospețime"], tip:"Se păstrează bine la temperatura camerei 3 zile, sau la frigider până la 2 săptămâni." },
  ds068: { name:"Bomboane inspirate din Almond Joy", steps:["Amestecă nuca de cocos, uleiul de cocos, mierea și vanilia, până se formează o pastă groasă.","Dă la frigider 15 minute. Formează 12 forme ovale.","Presează câte o migdală în fiecare.","Scufundă fiecare în ciocolată neagră topită. Ține la frigider până se întăresc."], benefits:["Inspirate din Almond Joy — complet fără zahăr rafinat","MCT-urile din cocos se transformă rapid în energie","Migdalele adaugă vitamina E și grăsimi mononesaturate sănătoase"], tip:"Răcește bine umplutura de cocos înainte de a o scufunda în ciocolată, pentru o acoperire mai îngrijită." },
  ds069: { name:"Bomboane tip clătită, cu banane și ovăz", steps:["Preîncălzește cuptorul la 180°C. Unge o tavă pentru 12 brioșe.","Mixează fulgii de ovăz până devin o făină fină.","Amestecă banana, ouăle, vanilia și scorțișoara. Adaugă făina de ovăz și praful de copt.","Încorporează afinele. Împarte în formele de brioșe.","Coace 12-15 minute, până se leagă."], benefits:["Doar 82 kcal per bucată — bune pentru o gustare atentă la calorii","Fără zahăr rafinat sau făină — opțiune fără gluten","Afinele adaugă antioxidanți și vitamina C"], tip:"Servește cu un fir de miere sau sirop de arțar pur, pentru o combinație distractivă de mic dejun și desert." },
  ds070: { name:"Fursecuri condimentate cu dovleac", steps:["Preîncălzește cuptorul la 175°C. Tapetează o tavă de copt.","Amestecă piureul de dovleac, siropul de arțar și uleiul de cocos.","Încorporează fulgii de ovăz, făina de migdale și condimentele, până se combină.","Formează grămăjoare de mărimea unei linguri, pe tavă. Aplatizează ușor.","Coace 14-16 minute, până devin ferme și rumenite."], benefits:["Dovleacul este plin de beta-caroten, vitamina C și potasiu","Amestecul de condimente calde susține circulația și digestia","Sub 100 kcal per fursec"], tip:"Aceste fursecuri au un gust și mai bun a doua zi, după ce se dezvoltă aromele condimentelor." },
  ds071: { name:"Tartă de cocos și lămâie", steps:["Bază: mixează migdalele, nuca de cocos și curmalele, până devin lipicioase. Presează într-o tavă de tartă tapetată.","Umplutură: mixează caju, zeama și coaja de lămâie, uleiul de cocos și mierea, până obții o cremă fină și mătăsoasă.","Toarnă umplutura peste bază. Congelează 2 ore, până se întărește.","Lasă la decongelat 10 minute înainte de a tăia. Decorează cu coajă de lămâie."], benefits:["Lămâia oferă vitamina C și acid citric alcalinizant","Caju creează o textură cremoasă de curd, fără lactate","Fără cereale și fără zahăr rafinat"], tip:"Folosește o tavă de tartă cu fund detașabil, pentru scoatere ușoară și un finisaj îngrijit." },
  ds072: { name:"Boluri de tip banana split", steps:["Taie bananele pe lungime, în jumătate, și așază-le în boluri.","Așază căpșunile și ananasul alături.","Pune iaurtul grecesc cu lingura, în centru.","Toarnă sos de ciocolată deasupra și presară nuci zdrobite.","Servește imediat."], benefits:["Banana split clasic, reinventat doar cu alimente integrale","Trei fructe oferă un spectru larg de vitamine și antioxidanți","Conținut ridicat de potasiu și fibre"], tip:"Prepară sosul de ciocolată încălzind 1 lingură de ciocolată neagră cu 1 linguriță de ulei de cocos." },
  ds073: { name:"Tarte de cocos cu zmeură", steps:["Bază: procesează migdalele, nuca de cocos și curmalele, până devin o crumbă lipicioasă. Presează în 8 forme de tartă.","Mixează caju, zmeura, mierea și uleiul de cocos, până devin fine.","Toarnă umplutura peste bază. Congelează 2 ore.","Decorează cu câteva zmeure proaspete. Lasă la decongelat 5 minute înainte de servire."], benefits:["Zmeura conține acid elagic și cel mai ridicat conținut de fibre dintre fructele de pădure obișnuite","Crema de caju este o alternativă versatilă, fără lactate","Culoare roz frumoasă, complet din fruct natural"], tip:"Adaugă un vârf de apă de trandafiri în crema de zmeură, pentru o notă florală romantică." },
  ds074: { name:"Bomboane de tip turtă dulce cu ghimbir", steps:["Mixează făina de migdale, curmalele, ghimbirul, scorțișoara și uleiul de cocos, până se formează un aluat.","Adaugă melasa, dacă o folosești — amestecă bine.","Formează 14 bile.","Dă fiecare bilă prin ghimbir cristalizat, tocat fin.","Ține la frigider 20 de minute înainte de servire."], benefits:["Ghimbirul proaspăt are proprietăți puternice antigreață și antiinflamatorii","Profil aromatic de turtă dulce, fără zahăr rafinat","Făina de migdale oferă proteine și vitamina E"], tip:"Dublează cantitatea de ghimbir pentru o gustare îndrăzneață și încălzitoare, perfectă pentru lunile de iarnă." },
  ds075: { name:"Budincă de ciocolată cu quinoa", steps:["Încălzește laptele de cocos cu cacaua și mierea, amestecând cu telul până devine fin.","Adaugă quinoa fiartă și vanilia.","Fierbe la foc mic 5 minute, amestecând, până se îngroașă, ca o budincă de orez.","Adaugă fulgii de ciocolată. Servește caldă sau rece."], benefits:["Quinoa este o proteină completă, cu toți cei 9 aminoacizi esențiali","Mai bogată în proteine decât orice altă budincă pe bază de cereale","Pofta de ciocolată e satisfăcută cu antioxidanții cacaoului real"], tip:"Adaugă deasupra un fir de unt de migdale și un vârf de fulgi de sare de mare, pentru mai multă răsfățare." },
  ds076: { name:"Batoane fudge cu unt de arahide", steps:["Amestecă untul de arahide, uleiul de cocos, mierea și vanilia, până devine fin.","Toarnă într-o tavă pătrată de 20cm, tapetată. Congelează 20 de minute, până se întărește.","Întinde ciocolata topită uniform deasupra. Presară fulgi de sare.","Congelează încă 30 de minute. Taie în 16 batoane."], benefits:["Bogate în proteine și sățioase — ideale pentru a tempera poftele de dulce","Stratul de ciocolată adaugă flavanoli antioxidanți","Fără zahăr rafinat, nu necesită coacere"], tip:"Stratul de fudge trebuie să fie foarte rece înainte de a adăuga ciocolata — altfel se topește în interior." },
  ds077: { name:"Cupe de fursecuri cu ovăz și fulgi de ciocolată", steps:["Preîncălzește cuptorul la 180°C. Unge o tavă de 12 mini-brioșe.","Amestecă untul de migdale, mierea, oul și vanilia.","Încorporează fulgii de ovăz, bicarbonatul de sodiu, sarea și fulgii de ciocolată.","Presează amestecul în formele tăvii.","Coace 12-14 minute, până se leagă. Lasă la răcit înainte de a le scoate."], benefits:["Beta-glucanul din ovăz susține reglarea colesterolului și a glicemiei","Coapte în forme individuale — porții perfecte, ușor de servit","Fără făină sau zahăr rafinat"], tip:"Presară câțiva fulgi de ciocolată în plus deasupra, după coacere, pentru un aspect impecabil." },
  ds078: { name:"Granită de pepene galben cu mentă", steps:["Mixează pepenele, lime-ul, menta și mierea, până devin fine.","Toarnă într-un vas plat, pentru congelator.","Congelează 1 oră, apoi răzuiește cu o furculiță la fiecare 30 de minute, timp de 2-3 ore.","Servește în pahare reci, cu o crenguță de mentă."], benefits:["Doar 50 kcal — unul dintre cele mai ușoare deserturi posibile","Pepenele galben este bogat în vitamina C și potasiu","Răcoritor și rece — perfect pentru vară"], tip:"Adaugă un vârf de cayenne pentru o granită surprinzătoare, cu pepene, chili și lime." },
  ds079: { name:"Cupe de ciocolată cu tahini", steps:["Tapetează o tavă de 10 mini-brioșe cu forme de hârtie.","Toarnă puțină ciocolată în fiecare formă. Congelează 5 minute.","Amestecă tahini, mierea și vanilia. Toarnă peste ciocolată.","Acoperă cu restul de ciocolată, semințe de susan și fulgi de sare.","Congelează 20 de minute, până se întăresc."], benefits:["Tahini este una dintre cele mai bune surse vegetale de calciu","Susanul conține sesamină și sesamolină, benefice pentru ficat","Inspirat din halva — arome din Orientul Mijlociu, într-o cupă sănătoasă"], tip:"Folosește tahini fluid (nu pastă groasă), pentru cea mai fină umplutură." },
  ds080: { name:"Pătrățele cu afine și ovăz", steps:["Preîncălzește cuptorul la 180°C. Tapetează o tavă de 20x20cm.","Amestecă fulgii de ovăz, făina de migdale, uleiul de cocos și jumătate din miere. Rezervă ⅓ pentru deasupra.","Presează ⅔ din amestecul de ovăz în tavă, pentru bază.","Amestecă afinele cu restul de miere, lămâia și scorțișoara. Întinde peste bază.","Presară amestecul de ovăz rezervat deasupra afinelor.","Coace 28-32 de minute, până se rumenește. Lasă la răcit complet înainte de a tăia."], benefits:["Afinele oferă pterostilben, benefic pentru creier și memorie","Beta-glucanul din ovăz susține bacteriile intestinale și colesterolul","Portabile și potrivite pentru mesele pregătite din timp"], tip:"Dă la frigider înainte de a tăia, pentru pătrățele cu margini perfect curate." },
  ds081: { name:"Panna cotta cu mușețel și miere", steps:["Dizolvă gelatina în 3 linguri de apă rece. Lasă 5 minute, să se hidrateze.","Încălzește laptele de cocos până începe să aburească. Lasă plicurile de mușețel la infuzat 5 minute. Scoate-le.","Amestecă mierea, vanilia și gelatina, până se dizolvă complet.","Toarnă în pahare sau forme. Dă la frigider minimum 4 ore.","Servește cu un fir de miere și flori uscate de mușețel."], benefits:["Mușețelul este un calmant natural, care favorizează somnul și reduce anxietatea","Elegant și terapeutic — potrivit mai ales ca desert de seară","Fără lactate, cu cremozitatea bogată a cocosului"], tip:"Nu lăsa laptele de cocos să dea în clocot — infuzarea mușețelului în lapte doar cald scoate cea mai bună aromă." },
  ds082: { name:"Batoane cu mere, scorțișoară și ovăz", steps:["Preîncălzește cuptorul la 180°C. Tapetează o tavă de 20x30cm.","Stoarce excesul de umezeală din mărul ras.","Amestecă toate ingredientele împreună, până se combină.","Presează ferm în tavă.","Coace 25-30 de minute, până se rumenește. Lasă la răcit complet înainte de a tăia în 12 batoane."], benefits:["Pectina din mere este una dintre cele mai bune fibre prebiotice din natură","Scorțișoara caldă ajută la reglarea glicemiei după masă","Portabile, se păstrează bine 4 zile"], tip:"Adaugă un pumn de stafide sau merișoare uscate, pentru mai multă dulceață și textură." },
  ds083: { name:"Parfait de chia cu zmeură și trandafir", steps:["Amestecă semințele de chia, laptele de migdale, mierea și apa de trandafiri. Amestecă bine.","Dă la frigider minimum 2 ore, până devine gros, ca o budincă.","Așază în straturi budinca de chia, iaurtul de cocos și zmeura, în pahare.","Decorează cu fistic tocat.","Servește rece."], benefits:["9g de fibre per porție — excepțional pentru sănătatea digestivă","Apa de trandafiri adaugă o notă florală elegantă, cu beneficii digestive","Fisticul oferă fibre prebiotice și proteine complete"], tip:"Prepară stratul de chia cu o seară înainte, pentru cea mai cremoasă textură, bine legată." },
};

export default dessertsRo;
